const body = $input.first().json.body || $input.first().json;
const question = body.question;
if (!question || question.trim() === '') {
  throw new Error('Поле "question" обязательно');
}
return [{
  json: {
    question: question.trim(),
    subject: body.subject || null,
    grade: body.grade || null,
    top_k: body.top_k || 5,
    llm: body.llm || 'local'
  }
}];

const queryData = $('2. Валидация').first().json;
const embedResponse = $input.first().json;
let embedding = embedResponse.embedding;
if (!embedding) throw new Error('Не удалось получить embedding');
const embeddingStr = '[' + embedding.join(',') + ']';
return [{
  json: {
    question: queryData.question,
    subject: queryData.subject,
    grade: queryData.grade,
    top_k: queryData.top_k,
    llm: queryData.llm,
    query_embedding: embeddingStr
  }
}];

const question = $('2. Валидация').first().json.question;
const llm = $('4. Подготовка').first().json.llm;
const results = $input.all();

let lang = 'ro';
if (/[а-яА-ЯёЁ]/.test(question)) lang = 'ru';
else if (/^(what|who|where|when|why|how|is|are|do|does|can|could)/i.test(question)) lang = 'en';

const langInstructions = {
  'ru': 'ВАЖНО: Отвечай ТОЛЬКО на русском языке!',
  'en': 'IMPORTANT: Answer ONLY in English!',
  'ro': 'Răspunde în limba română.'
};

let context = '';
let sources = [];
results.forEach((item, i) => {
  const doc = item.json;
  context += `[Источник ${i+1}: ${doc.title || doc.book_id}]\n${doc.content}\n\n`;
  sources.push({ title: doc.title || doc.book_id, subject: doc.subject, similarity: doc.similarity?.toFixed(2) || 'N/A' });
});

const systemPrompt = `Ты - образовательный ассистент EDU RAG.\n${langInstructions[lang]}\nОтвечай ТОЛЬКО на основе контекста. Цитируй источники.`;

return [{
  json: { question, context, sources, lang, llm, systemPrompt }
}];

