const contextData = $('6. Контекст').first().json;
const llmResponse = $input.first().json;

let answer = '';
let thinking = '';
let llmUsed = contextData.llm;

// GPT response
if (llmResponse.choices && llmResponse.choices[0]) {
  answer = llmResponse.choices[0].message.content;
  llmUsed = 'gpt-5-nano';
}
// Ollama response (DeepSeek-R1 with thinking)
else if (llmResponse.message && llmResponse.message.content) {
  let fullResponse = llmResponse.message.content;
  llmUsed = 'deepseek-r1:8b';

  // Extract thinking from <think>...</think> tags
  const thinkMatch = fullResponse.match(/<think>([\s\S]*?)<\/think>/i);
  if (thinkMatch) {
    thinking = thinkMatch[1].trim();
    answer = fullResponse.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  } else {
    answer = fullResponse;
  }
} else {
  answer = 'Не удалось сгенерировать ответ.';
}

const result = {
  success: true,
  question: contextData.question,
  answer: answer,
  sources: contextData.sources,
  llm: llmUsed
};

if (thinking) {
  result.thinking = thinking;
}

return [{ json: result }];
